import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"03 · Demo 预览","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/honey-butter/03-demo-preview.md","filePath":"lab/shuangyu-fries/honey-butter/03-demo-preview.md","lastUpdated":1787456457000}'),d={name:"lab/shuangyu-fries/honey-butter/03-demo-preview.md"};function o(r,a,i,l,p,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="_03-·-demo-预览" tabindex="-1">03 · Demo 预览 <a class="header-anchor" href="#_03-·-demo-预览" aria-label="Permalink to &quot;03 · Demo 预览&quot;">​</a></h1><blockquote><p>内部方向预览 ｜ 12 秒 / 9:16 ｜ 只验证创意、调性、动作可行性与节奏</p></blockquote><h2 id="demo-的职责" tabindex="-1">Demo 的职责 <a class="header-anchor" href="#demo-的职责" aria-label="Permalink to &quot;Demo 的职责&quot;">​</a></h2><p>关键帧通过后，先用最小生成量拼出一条 12 秒预览。此时不追求逐帧产品保真，也不为某个失败动作重写全部镜头；只回答四个问题：</p><ol><li>第一秒的声音选择题是否能看懂？</li><li>A / B / C 三个动作是否有足够差异？</li><li>5.4–8.1 秒的 remix 是否形成节奏高潮？</li><li>「答案：都是」和产品落版是否拥挤？</li></ol><div class="warning custom-block"><p class="custom-block-title">Demo 不是成片底料</p><p>Demo 可保留节奏、镜头顺序和通过的单段动作，但不能默认直接进入最终交付。平台水印、产品漂移、假包装、伪文字和不稳定手部必须在正式分镜阶段重做。</p></div><h2 id="最小预览包" tabindex="-1">最小预览包 <a class="header-anchor" href="#最小预览包" aria-label="Permalink to &quot;最小预览包&quot;">​</a></h2><p>只生成四段动态，其余镜头使用已审核关键帧和后期版式完成。</p><table tabindex="0"><thead><tr><th>素材</th><th>输入</th><th style="text-align:right;">动作窗口</th><th>用途</th></tr></thead><tbody><tr><td>DV02 · 单根折断</td><td>KF02A + KF02B</td><td style="text-align:right;">1.0s</td><td>A 声纹</td></tr><tr><td>DV03 · 双根折断</td><td>KF03A + KF03B</td><td style="text-align:right;">1.1s</td><td>B 声纹</td></tr><tr><td>DV04 · 咬下</td><td>KF04A + KF04B</td><td style="text-align:right;">1.2s</td><td>C 声纹</td></tr><tr><td>DV08 · 断面轻转</td><td>KF08</td><td style="text-align:right;">1.3s</td><td>remix 第四拍与答案证据</td></tr></tbody></table><p>镜头 01、05、07、09 在 Demo 中使用静帧数字推近和后期排版，不额外消耗视频生成次数。镜头 06 直接由 DV02、DV03、DV04、DV08 各截 0.25–0.4 秒拼成。</p><h2 id="demo-视频-prompt" tabindex="-1">Demo 视频 Prompt <a class="header-anchor" href="#demo-视频-prompt" aria-label="Permalink to &quot;Demo 视频 Prompt&quot;">​</a></h2><h3 id="dv02-·-单根折断" tabindex="-1">DV02 · 单根折断 <a class="header-anchor" href="#dv02-·-单根折断" aria-label="Permalink to &quot;DV02 · 单根折断&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Editorial action window: exactly 1.0 second.</span></span>
<span class="line"><span>Use the approved KF02A and KF02B as strict first and last frames. One continuous uncut vertical 9:16</span></span>
<span class="line"><span>macro shot. Lock the camera, focus, exposure, product scale, clamp positions and background.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The two edge clamps apply one short opposing force. The single rigid potato crisp snaps exactly once at</span></span>
<span class="line"><span>the center and reaches the supplied end frame. Preserve the exact P0 length, thickness, pale-golden color,</span></span>
<span class="line"><span>dry creamy-yellow seasoning and M0 fracture material. Only 5-8 small food crumbs fall under gravity.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No camera movement, no bending, no repeated fracture, no healing, no extra product, no dust cloud,</span></span>
<span class="line"><span>no text, no packaging, no logo, no watermark and no generated audio required.</span></span></code></pre></div><h3 id="dv03-·-双根折断" tabindex="-1">DV03 · 双根折断 <a class="header-anchor" href="#dv03-·-双根折断" aria-label="Permalink to &quot;DV03 · 双根折断&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Editorial action window: exactly 1.1 seconds.</span></span>
<span class="line"><span>Use KF03A and KF03B as strict first and last frames. One continuous uncut vertical 9:16 shot. Keep both</span></span>
<span class="line"><span>P0 crisps separate, parallel and identical in thickness. The upper crisp snaps first; the lower crisp</span></span>
<span class="line"><span>follows 20-60 milliseconds later. Both actions happen once and settle into the supplied end frame.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Preserve exact product identity and M0 fracture material. Crumbs remain sparse and obey gravity.</span></span>
<span class="line"><span>Locked camera and stable exposure. Exclude product fusion, synchronized explosion, third product,</span></span>
<span class="line"><span>bending, morphing, camera move, text, packaging, logo, watermark and generated audio.</span></span></code></pre></div><h3 id="dv04-·-咬下" tabindex="-1">DV04 · 咬下 <a class="header-anchor" href="#dv04-·-咬下" aria-label="Permalink to &quot;DV04 · 咬下&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Editorial action window: exactly 1.2 seconds.</span></span>
<span class="line"><span>Use KF04A and KF04B as strict first and last frames. Keep the same lower-face identity, side angle,</span></span>
<span class="line"><span>lighting and P0 product scale. The product pauses near the lips for 0.2 seconds, then one small front</span></span>
<span class="line"><span>section is bitten off in a single natural action. The remaining product keeps its exact rigid geometry</span></span>
<span class="line"><span>and reaches the supplied end frame.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No full face reveal, no exaggerated expression, no chewing loop, no saliva, no extra teeth, no warped</span></span>
<span class="line"><span>mouth, no product penetration, no packaging text, no logo, no watermark and no generated audio.</span></span></code></pre></div><h3 id="dv08-·-断面轻转" tabindex="-1">DV08 · 断面轻转 <a class="header-anchor" href="#dv08-·-断面轻转" aria-label="Permalink to &quot;DV08 · 断面轻转&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Editorial action window: exactly 1.3 seconds.</span></span>
<span class="line"><span>Animate the approved KF08 only. One rigid broken P0 crisp makes a subtle three-quarter turn of less than</span></span>
<span class="line"><span>12 degrees while the locked macro camera holds. Focus moves once from the dry outer surface to the M0-</span></span>
<span class="line"><span>matched fracture face. Preserve all geometry, pore scale, crumbs, color and seasoning without change.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No orbit, no push-in, no second product, no new fracture, no oversized pores, no glow, no liquid,</span></span>
<span class="line"><span>no text, no packaging, no logo, no watermark and no generated audio.</span></span></code></pre></div><h2 id="_12-秒预览拼法" tabindex="-1">12 秒预览拼法 <a class="header-anchor" href="#_12-秒预览拼法" aria-label="Permalink to &quot;12 秒预览拼法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>使用素材</th><th>Demo 处理</th></tr></thead><tbody><tr><td>00:00.0–00:00.9</td><td>KF01</td><td>数字推近 2%；后期加问题</td></tr><tr><td>00:00.9–00:01.9</td><td>DV02</td><td>完整使用；后期加 A</td></tr><tr><td>00:01.9–00:03.0</td><td>DV03</td><td>完整使用；后期加 B</td></tr><tr><td>00:03.0–00:04.2</td><td>DV04</td><td>完整使用；后期加 C</td></tr><tr><td>00:04.2–00:05.4</td><td>KF05</td><td>静帧；后期加三条临时波形和「你选哪一声？」</td></tr><tr><td>00:05.4–00:08.1</td><td>四段动态</td><td>按 A–B–C–断面剪成四拍</td></tr><tr><td>00:08.1–00:09.0</td><td>KF05</td><td>三条波形合一；后期加「答案：都是。」</td></tr><tr><td>00:09.0–00:10.3</td><td>DV08</td><td>使用完整动作；后期加核心文案</td></tr><tr><td>00:10.3–00:12.0</td><td>KF09</td><td>合成确认包装；数字推近不超过 2%</td></tr></tbody></table><p>Demo 阶段使用临时 Foley 和临时音乐，只用于判断节拍。正式声音资产见 <a href="./05-sound-edit">05 · 声音与剪辑</a>。</p><h2 id="预览反馈记录" tabindex="-1">预览反馈记录 <a class="header-anchor" href="#预览反馈记录" aria-label="Permalink to &quot;预览反馈记录&quot;">​</a></h2><p>审核只记录方向问题，不在此阶段逐帧修图。</p><table tabindex="0"><thead><tr><th>审核项</th><th>结论</th><th>需要带入正式分镜的修改</th></tr></thead><tbody><tr><td>第一秒钩子</td><td>待审核</td><td></td></tr><tr><td>A / B / C 可区分性</td><td>待审核</td><td></td></tr><tr><td>remix 节奏</td><td>待审核</td><td></td></tr><tr><td>答案反转</td><td>待审核</td><td></td></tr><tr><td>包装落版</td><td>待审核</td><td></td></tr><tr><td>整体食欲感</td><td>待审核</td><td></td></tr></tbody></table><h2 id="demo-通过门禁" tabindex="-1">Demo 通过门禁 <a class="header-anchor" href="#demo-通过门禁" aria-label="Permalink to &quot;Demo 通过门禁&quot;">​</a></h2><ul><li>[ ] 0.9 秒内能理解问题，且不需要额外玩法说明</li><li>[ ] A / B / C 三个动作一眼可区分</li><li>[ ] 四个动态素材均从已审核关键帧生成</li><li>[ ] 产品形态虽允许轻微漂移，但没有变成膨化棒、饼干或威化</li><li>[ ] remix 有清楚的四拍递进，答案出现时不过度拥挤</li><li>[ ] 假包装、模型文字、水印和 Demo 音频不会进入正式交付</li><li>[ ] 已记录需要带入正式分镜的具体修改</li></ul><hr><p><strong>上一步</strong> ← <a href="./02-keyframes">02 · 关键帧</a> ｜ <strong>下一步</strong> → <a href="./04-storyboard">04 · 分镜</a></p>`,29)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
